import os
import sqlite3
import glob

print("CWD:", os.getcwd())
for entry in sorted(os.listdir(".")):
    print("ENTRY:", entry)

for pattern in ("*.db", "*.sqlite", "*.sqlite3", "*.db3"):
    for db_path in glob.glob(pattern):
        print("=" * 60)
        print("DB:", db_path)
        try:
            with sqlite3.connect(db_path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                rows = cur.execute(
                    "SELECT name, type FROM sqlite_master WHERE type IN ('table','view') ORDER BY name"
                ).fetchall()
                for row in rows:
                    print("OBJECT:", dict(row))
                    if row["type"] == "table":
                        schema = cur.execute(
                            "SELECT sql FROM sqlite_master WHERE name = ?", (row["name"],)
                        ).fetchone()
                        print("SCHEMA:", schema[0] if schema else None)
                        count = cur.execute(
                            f'SELECT COUNT(*) FROM "{row["name"]}"'
                        ).fetchone()
                        print("ROWS:", count[0])
        except Exception as exc:
            print("ERROR:", type(exc).__name__, exc)

